qwen3_sql:
SELECT CI_ID, HOST_NAME 
FROM t_bz_config_ci_ne_root 
WHERE IS_ONLINE = 1 AND IS_DELETED = 0;

SELECT COUNT(*) AS total_active_devices
FROM t_bz_config_ci_ne_root
WHERE IS_ACTIVE = 1 AND IS_DELETED = 0;

SELECT CI_ID, HOST_NAME 
FROM t_bz_config_ci_ne_root 
WHERE IS_ONLINE = 0 AND IS_DELETED = 0;

SELECT COUNT(*) AS total_active_customers
FROM t_bz_config_customer
WHERE IS_ACTIVE = 1;

SELECT CUSTOMER_ID, CUSTOMER_PHONE
FROM t_bz_config_customer
WHERE CUSTOMER_ABB = '上海理想';

SELECT c.CUSTOMER_EMAIL
FROM t_bz_config_customer c
WHERE c.CUSTOMER_NAME = '中国电信上海理想';

SELECT COUNT(*) AS alarm_count
FROM event_history
WHERE DATE(EVENT_TIME) = DATE(DATE_SUB(NOW(), INTERVAL 1 DAY));

SELECT COUNT(*) AS alarm_count
FROM event_history
WHERE EVENT_TIME >= DATE_SUB(NOW(), INTERVAL 30 DAY);

SELECT COUNT(*) AS warning_count
FROM event_sdn
WHERE perceived_severity = '警告';

SELECT COUNT(*) AS online_device_count
FROM t_bz_config_ci_ne_root
WHERE IS_ONLINE = 1 AND IS_DELETED = 0;

SELECT CUSTOMER_ID 
FROM t_bz_config_customer 
WHERE CUSTOMER_ABB = 'ngg-319009';

SELECT e.EVENT_ID, e.EVENT_NAME
FROM event_history e
WHERE e.EVENT_TIME >= NOW() - INTERVAL 7 DAY;

SELECT CI_ID, NE_ID, NE_IP, NE_MODEL, HOST_NAME, SERIAL_NUMBER, STATUS, IS_ONLINE
FROM t_bz_config_ci_ne_root
WHERE NE_MODEL IS NULL OR NE_MODEL = '' OR TRIM(NE_MODEL) = '';

SELECT DISTINCT native_probable_cause AS alarm_name
FROM event_sdn
WHERE perceived_severity = '警告';

SELECT CREATE_TIME 
FROM t_bz_config_customer 
WHERE CUSTOMER_NAME = '上海理想公司';

SELECT COUNT(DISTINCT REGION_ID) AS distinct_region_count
FROM t_bz_config_ci_ne_root
WHERE IS_DELETED = 0;

SELECT HOST_NAME, NE_IP 
FROM t_bz_config_ci_ne_root 
WHERE IS_ONLINE = 1 AND IS_DELETED = 0;

SELECT c.CUSTOMER_NAME, c.CUSTOMER_PHONE
FROM t_bz_config_customer c
WHERE c.IS_ACTIVE = 1;

SELECT CUSTOMER_NAME 
FROM t_bz_config_customer 
WHERE CUSTOMER_ABB = 'ngg-319009';

SELECT COUNT(*) AS alarm_count
FROM event_history
WHERE SEVERITY_NAME = '严重' AND EVENT_STATUS = 1 AND deleted = 0;

SELECT EVENT_NAME, EVENT_TIME 
FROM event_history 
WHERE EVENT_TYPE_NAME = 'Ping event';

SELECT e.EVENT_ID, e.EVENT_NAME
FROM event_history e
WHERE e.EVENT_STATUS = 1 AND e.EVENT_STATUS_NAME = '已恢复';

SELECT COUNT(*) AS alarm_count
FROM event_sdn
WHERE time_created >= DATE_SUB(NOW(), INTERVAL 7 DAY);

SELECT EVENT_DESC 
FROM event_history 
WHERE SEVERITY_NAME = '警告';

SELECT * FROM event_history 
WHERE EVENT_TIME >= DATE_FORMAT(NOW(), '%Y-%m-01 00:00:00') 
  AND EVENT_TIME < DATE_FORMAT(DATE_ADD(NOW(), INTERVAL 1 MONTH), '%Y-%m-01 00:00:00');

SELECT DISTINCT EVENT_TYPE_NAME 
FROM event_history 
WHERE IS_DELETED = 0;

SELECT HOST_NAME 
FROM t_bz_config_ci_ne_root 
WHERE IS_ACTIVE = 0 AND IS_DELETED = 0;

SELECT COUNT(*) AS customer_count
FROM t_bz_config_customer
WHERE CUSTOMER_EMAIL IS NOT NULL AND CUSTOMER_EMAIL != '';

SELECT HOST_NAME, NE_IP 
FROM t_bz_config_ci_ne_root 
WHERE IS_ONLINE = 1 AND IS_DELETED = 0;

SELECT *
FROM t_bz_config_ci_ne_root
WHERE IS_ONLINE = 0 AND IS_DELETED = 0;

SELECT COUNT(*) AS active_device_count
FROM t_bz_config_ci_ne_root
WHERE IS_ACTIVE = 1 AND IS_DELETED = 0;

SELECT COUNT(*) AS total_customers
FROM t_bz_config_customer
WHERE IS_ACTIVE = 1;

SELECT CUSTOMER_ID, CUSTOMER_NAME, CUSTOMER_ABB, CUSTOMER_DESC
FROM t_bz_config_customer
WHERE CUSTOMER_ABB LIKE '%ngg%';

SELECT COUNT(*) AS alarm_count
FROM event_sdn
WHERE DATE(time_created) = DATE(DATE_SUB(NOW(), INTERVAL 1 DAY));

SELECT e.EVENT_NAME, e.EVENT_TIME
FROM event_history e
WHERE e.SEVERITY_NAME = '警告';
